"""User-supplied default sidebar icons, resized to 96 px for TV/web navigation.

Source originals: home-2.png, movie-2.png, quiz.png, cogwheel.png.
The PNGs are stored as embedded, offline-safe, indexed images.
"""
from base64 import b64decode

ICONS = {
    "home": "",
    "movies": "",
    "tv": "",
    "settings": "",
}

def default_icon_png(name: str) -> bytes:
    return b64decode(ICONS[name])
